import torch
import torch.nn as nn
import triton
import triton.language as tl


def _to_pair(x):
    return (x, x) if isinstance(x, int) else tuple(x)


@triton.autotune(
    configs=[
        triton.Config(
            {
                "BLOCK_M": 32,
                "BLOCK_N": 32,
                "BLOCK_K": 32,
                "GROUP_M": 8,
                "grf_mode": "128",
            },
        ),
    ],
    key=["C_IN", "C_out", "OH", "OW"],
)
@triton.jit
def _conv2d_dilated_gemm(
    x_ptr,
    w_ptr,
    y_ptr,
    N_batch,
    H_in,
    W_in,
    C_out,
    OH,
    OW,
    sxn,
    sxh,
    sxw,
    swkh,
    swkw,
    swci,
    swco,
    syn,
    syh,
    syw,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_M: tl.constexpr,
    PAD_H: tl.constexpr,
    PAD_W: tl.constexpr,
    DIL_H: tl.constexpr,
    DIL_W: tl.constexpr,
    KH: tl.constexpr,
    KW: tl.constexpr,
    C_IN: tl.constexpr,
    grf_mode: tl.constexpr,
):
    pid = tl.program_id(0)
    M_total = N_batch * OH * OW
    num_pid_m = tl.cdiv(M_total, BLOCK_M)
    num_pid_n = tl.cdiv(C_out, BLOCK_N)
    num_pid_in_group = GROUP_M * num_pid_n
    group_id = pid // num_pid_in_group
    first_pid_m = group_id * GROUP_M
    group_size_m = tl.minimum(num_pid_m - first_pid_m, GROUP_M)
    pid_in_group = pid % num_pid_in_group
    pid_m = first_pid_m + (pid_in_group % group_size_m)
    pid_n = pid_in_group // group_size_m

    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    offs_k = tl.arange(0, BLOCK_K)

    ohw = OH * OW
    n_idx = offs_m // ohw
    rem = offs_m % ohw
    oh_idx = rem // OW
    ow_idx = rem % OW

    mask_m = offs_m < M_total
    mask_n = offs_n < C_out

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    x_base = x_ptr + n_idx.to(tl.int64) * sxn

    for kh in range(KH):
        for kw in range(KW):
            ih = oh_idx + kh * DIL_H - PAD_H
            iw = ow_idx + kw * DIL_W - PAD_W
            valid = (ih >= 0) & (ih < H_in) & (iw >= 0) & (iw < W_in) & mask_m
            x_hw_ptrs = x_base + ih * sxh + iw * sxw

            w_bp = tl.make_block_ptr(
                base=w_ptr + kh * swkh + kw * swkw,
                shape=(C_IN, C_out),
                strides=(swci, swco),
                offsets=(0, pid_n * BLOCK_N),
                block_shape=(BLOCK_K, BLOCK_N),
                order=(1, 0),
            )

            for c0 in range(0, C_IN, BLOCK_K):
                k_idx = c0 + offs_k
                x_tile = tl.load(
                    x_hw_ptrs[:, None] + k_idx[None, :],
                    mask=valid[:, None] & (k_idx[None, :] < C_IN),
                    other=0.0,
                )
                w_tile = tl.load(w_bp, boundary_check=(0, 1), padding_option="zero")
                acc = tl.dot(x_tile, w_tile, acc)
                w_bp = tl.advance(w_bp, (BLOCK_K, 0))

    y_ptrs = y_ptr + n_idx.to(tl.int64) * syn + oh_idx * syh + ow_idx * syw
    tl.store(
        y_ptrs[:, None] + offs_n[None, :],
        acc.to(y_ptr.dtype.element_ty),
        mask=mask_m[:, None] & mask_n[None, :],
    )


class Model(nn.Module):
    def __init__(
        self,
        in_channels,
        out_channels,
        kernel_size,
        stride=1,
        padding=(0, 0),
        dilation=(1, 1),
        bias=False,
    ):
        super(Model, self).__init__()
        self.conv2d = nn.Conv2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            bias=bias,
        )
        self._stride = stride
        self._padding = _to_pair(padding)
        self._dilation = _to_pair(dilation)
        self._packed = False

    def _pack_weights(self):
        w = self.conv2d.weight.data
        self.w_packed = w.permute(2, 3, 1, 0).contiguous()
        self._packed = True

    def forward(self, x):
        if not self._packed:
            self._pack_weights()

        B, C_in, H_in, W_in = x.shape
        C_out = self.conv2d.weight.shape[0]
        KH, KW = self.conv2d.weight.shape[2], self.conv2d.weight.shape[3]
        pad_h, pad_w = self._padding
        dil_h, dil_w = self._dilation

        OH = (H_in + 2 * pad_h - dil_h * (KH - 1) - 1) + 1
        OW = (W_in + 2 * pad_w - dil_w * (KW - 1) - 1) + 1

        x_cl = x.contiguous(memory_format=torch.channels_last)
        y = torch.empty(
            B,
            C_out,
            OH,
            OW,
            device=x.device,
            dtype=x.dtype,
            memory_format=torch.channels_last,
        )

        sx = x_cl.stride()
        sy = y.stride()
        sw = self.w_packed.stride()

        M_total = B * OH * OW
        grid = lambda meta: (
            triton.cdiv(M_total, meta["BLOCK_M"]) * triton.cdiv(C_out, meta["BLOCK_N"]),
        )

        _conv2d_dilated_gemm[grid](
            x_cl,
            self.w_packed,
            y,
            B,
            H_in,
            W_in,
            C_out,
            OH,
            OW,
            sx[0],
            sx[2],
            sx[3],
            sw[0],
            sw[1],
            sw[2],
            sw[3],
            sy[0],
            sy[2],
            sy[3],
            PAD_H=pad_h,
            PAD_W=pad_w,
            DIL_H=dil_h,
            DIL_W=dil_w,
            KH=KH,
            KW=KW,
            C_IN=C_in,
        )

        if self.conv2d.bias is not None:
            y = y + self.conv2d.bias.view(1, -1, 1, 1)
        return y
